        return (0.0, 0.0)

    def depot_coord():
        if depot is None:
            return (0.0, 0.0)
        return normalize_point(depot)

    def coord_of(i):
        if i == 0:
            return depot_coord()
        if locations is None:
            return (0.0, 0.0)
        if isinstance(locations, dict):
            return normalize_point(locations.get(i, (0.0, 0.0)))
        try:
            if 0 <= i < len(locations):
                return normalize_point(locations[i])
        except Exception:
            pass
        return (0.0, 0.0)

    def demand_of(i):
        if demands is None:
            return 0
        if isinstance(demands, dict):
            v = demands.get(i, 0)
            try:
                return int(v)
            except Exception:
                return 0
        try:
            if 0 <= i < len(demands):
                v = demands[i]
                try:
                    return int(v)
                except Exception:
                    return 0
        except Exception:
            pass
        return 0

    def dist(a, b):
        ax, ay = coord_of(a)
        bx, by = coord_of(b)
        dx = ax - bx
        dy = ay - by
        return (dx * dx + dy * dy) ** 0.5

    if customers is None:
        if isinstance(demands, dict):
            customers = [k for k in demands.keys() if k != 0]
        else:
            try:
                customers = list(range(1, len(demands)))
            except Exception:
                if isinstance(locations, dict):
                    customers = [k for k in locations.keys() if k != 0]
                else:
                    try:
                        customers = list(range(1, len(locations)))
                    except Exception:
                        customers = []
    elif isinstance(customers, dict):
        customers = [k for k in customers.keys() if k != 0]
    else:
        try:
            customers = list(customers)
        except Exception:
            customers = []

    if capacity is None:
        total = 0
        for c in customers:
            total += demand_of(c)
        capacity = total if total > 0 else 1
    try:
        capacity = int(capacity)
        if capacity <= 0:
            capacity = 1
    except Exception:
        capacity = 1

    unrouted = sorted(customers, key=lambda c: (-dist(0, c), -demand_of(c), c))
    remaining = set(unrouted)
    routes = []

    while remaining:
        seed = None
        for c in unrouted:
            if c in remaining:
                seed = c
                break
        if seed is None:
            break

        route = [seed]
        load = demand_of(seed)
        remaining.remove(seed)

        while True:
            last = route[-1]
            best = None
            best_key = None
            for c in remaining:
                d = demand_of(c)
                if load + d > capacity:
                    continue
                key = (dist(last, c), -d, c)
                if best_key is None or key < best_key:
                    best_key = key
                    best = c
            if best is None:
                break
            route.append(best)
            load += demand_of(best)
            remaining.remove(best)

        routes.append(route)

    def route_load(r):
        s = 0
        for c in r:
            s += demand_of(c)
        return s

    def route_cost(r):
        if not r:
            return 0.0
        cost = dist(0, r[0]) + dist(r[-1], 0)
        for i in range(len(r) - 1):
            cost += dist(r[i], r[i + 1])
        return cost

    improved = True
    while improved:
        improved = False

        i = 0
        while i < len(routes):
            r = routes[i]
            n = len(r)
            best_gain = 0.0
            best_move = None
            if n >= 4:
                for a in range(n - 1):
                    for b in range(a + 2, n):
                        if a == 0 and b == n - 1:
                            continue
                        A = 0 if a == 0 else r[a - 1]
                        B = r[a]
                        C = r[b]
                        D = 0 if b == n - 1 else r[b + 1]
                        old = dist(A, B) + dist(C, D)
                        new = dist(A, C) + dist(B, D)
                        gain = old - new
                        if gain > best_gain + 1e-12:
                            best_gain = gain
                            best_move = (a, b)
            if best_move is not None:
                a, b = best_move
                routes[i] = r[:a] + r[a:b + 1][::-1] + r[b + 1:]
                improved = True
            i += 1

        i = 0
        while i < len(routes):
            if i >= len(routes):
                break
            j = i + 1
            while j < len(routes):
                if i >= len(routes) or j >= len(routes):
                    break
                ri = routes[i]
                rj = routes[j]
                li = route_load(ri)
                lj = route_load(rj)
                if li + lj <= capacity and ri and rj:
                    current = route_cost(ri) + route_cost(rj)
                    merged = [x for x in ri] + [x for x in rj]
                    if route_cost(merged) <= current + 1e-12:
                        routes[i] = merged
                        routes.pop(j)
                        improved = True
                        continue
                j += 1
            i += 1

        changed = True
        while changed:
            changed = False
            i = 0
            while i < len(routes):
                if changed:
                    break
                j = 0
                while j < len(routes):
                    if i == j:
                        j += 1
                        continue
                    if i >= len(routes) or j >= len(routes):
                        break
                    ri = routes[i]
                    rj = routes[j]
                    lj = route_load(rj)
                    best = None
                    best_delta = 0.0
                    best_pos = None
                    best_idx = None
                    for p in range(len(ri)):
                        c = ri[p]
                        dc = demand_of(c)
                        if lj + dc > capacity:
                            continue
                        prev = 0 if p == 0 else ri[p - 1]
                        nxt = 0 if p == len(ri) - 1 else ri[p + 1]
                        remove_cost = dist(prev, c) + dist(c, nxt) - dist(prev, nxt)
                        for q in range(len(rj) + 1):
                            left = 0 if q == 0 else rj[q - 1]
                            right = 0 if q == len(rj) else rj[q]
                            add_cost = dist(left, c) + dist(c, right) - dist(left, right)
                            delta = add_cost - remove_cost
                            if best is None or delta < best_delta:
                                best = c
                                best_delta = delta
                                best_pos = q
                                best_idx = p
                    if best is not None and best_delta < -1e-12:
                        c = ri.pop(best_idx)
                        if best_pos == 0:
                            rj.insert(0, c)
                        else:
                            rj.insert(best_pos, c)
                        if len(ri) == 0:
                            routes.pop(i)
                        improved = True
                        changed = True
                        break
                    j += 1
                i += 1

    return routes
